(()=>{const previous=shots;shots=function(){previous();const target=shotVideoTarget(),version=target&&selectedShotVideo(target),slot=document.getElementById('shotVideoPlayerSlot');if(!version||!slot)return;const cards=document.querySelectorAll('.shot-script-editor > .card'),host=cards[1];if(!host)return;const section=document.createElement('section');section.id='shotTopVideoPreview';section.style.cssText='margin-bottom:20px;padding-bottom:18px;border-bottom:1px solid #354556';const head=document.createElement('div');head.className='preview-head';const title=document.createElement('b');title.textContent=(target.shot_id||target.clip_id)+' · 已生成视频';const meta=document.createElement('span');meta.className='subtle';meta.textContent=(version.width||'?')+' × '+(version.height||'?')+' · '+Number(version.actual_duration_seconds||version.duration||target.duration)+'秒';head.append(title,meta);section.append(head);const note=slot.nextElementSibling;if(note?.tagName==='P'&&note.textContent.includes('当前播放版本'))section.append(slot,note);else section.append(slot);host.prepend(section);const original=document.querySelector('#shotVideoPanel > .preview-head b');if(original)original.textContent='视频生成设置';};render();})();